<!DOCTYPE html><html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1.0"><title>Jobs & Career - C-Net Library</title><meta name="description" content="Browse current government, private, internship and apprenticeship opportunities with official application links."><style>*{box-sizing:border-box}body{font-family:Inter,Arial,sans-serif;background:#f4f7fa;margin:0;color:#172033}.nav{background:#fff;border-bottom:1px solid #e3eaf0}.navin{max-width:1160px;margin:auto;padding:15px 20px;display:flex;justify-content:space-between;align-items:center;gap:16px}.brand{font-weight:850;font-size:20px;color:#102a43;text-decoration:none}.wrap{max-width:1160px;margin:28px auto;padding:0 20px}.hero{background:linear-gradient(135deg,#102a43,#164e63);color:#fff;border-radius:22px;padding:34px;margin-bottom:18px}.hero h1{font-size:38px;margin:0 0 8px}.hero p{color:#d8e4ec;max-width:700px}.filters,.card{background:#fff;border:1px solid #e1e8ef;border-radius:16px;padding:18px;margin-bottom:16px;box-shadow:0 6px 22px rgba(15,23,42,.035)}.grid{display:grid;grid-template-columns:2fr 1fr 1fr 1fr;gap:10px}.jobs{display:grid;grid-template-columns:1fr 1fr;gap:16px}.job{background:#fff;border:1px solid #e1e8ef;border-radius:17px;padding:20px;display:flex;flex-direction:column;box-shadow:0 6px 22px rgba(15,23,42,.035)}.job h2{color:#102a43;margin:10px 0 4px;font-size:22px}.muted{color:#718096}.tag{display:inline-block;background:#e8f5f2;color:#0f766e;padding:5px 9px;border-radius:999px;font-size:12px;font-weight:800;margin-right:5px}.tag.featured{background:#fff7ed;color:#9a3412}.deadline{font-weight:800;color:#9a3412}.btn{display:inline-flex;align-items:center;justify-content:center;background:#102a43;color:#fff;text-decoration:none;padding:10px 14px;border-radius:10px;border:1px solid #102a43;cursor:pointer;font-weight:750}.btn.alt{background:#fff;color:#102a43;border-color:#ccd7e1}.btn.green{background:#0f766e;border-color:#0f766e}.actions{display:flex;gap:8px;flex-wrap:wrap;margin-top:auto;padding-top:14px}input,select{width:100%;padding:11px;border:1px solid #ccd7e1;border-radius:10px;background:#fff}.filterActions{display:flex;gap:8px;margin-top:11px}.empty{grid-column:1/-1;text-align:center;padding:42px}.footnote{font-size:13px;color:#718096;margin-top:12px}@media(max-width:850px){.grid{grid-template-columns:1fr 1fr}.jobs{grid-template-columns:1fr}}@media(max-width:560px){.wrap{padding:0 14px}.navin{padding:13px 14px}.hero{padding:26px 20px}.hero h1{font-size:31px}.grid{grid-template-columns:1fr}.filterActions,.actions{flex-direction:column}.filterActions .btn,.actions .btn,.actions form,.actions form button{width:100%}}</style></head><body><nav class="nav"><div class="navin"><a class="brand" href="{{ route('home') }}">C-Net Library</a><div>@auth @if(auth()->user()->role==='student')<a class="btn alt" href="{{ route('student.dashboard') }}">Student Portal</a>@else<a class="btn alt" href="{{ route('home') }}">Home</a>@endif @else<a class="btn alt" href="{{ route('login') }}">Student Login</a>@endauth</div></div></nav><div class="wrap"><div class="hero"><h1>Jobs & Career Opportunities</h1><p>Discover current opportunities, shortlist relevant jobs and continue to the employer or recruitment body's official application page.</p>@auth @if(auth()->user()->role==='student')<a class="btn alt" href="{{ route('student.saved-jobs.index') }}">View My Saved Jobs</a>@endif @endauth</div>@if(session('success'))<div class="card" style="border-color:#86efac;background:#f0fdf4">{{ session('success') }}</div>@endif<form class="filters" method="GET"><div class="grid"><input type="search" name="q" value="{{ request('q') }}" placeholder="Job title, organization or category"><select name="type"><option value="">All job types</option>@foreach(['government','private','internship','apprenticeship'] as $type)<option value="{{ $type }}" @selected(request('type')===$type)>{{ ucfirst($type) }}</option>@endforeach</select><input name="qualification" value="{{ request('qualification') }}" placeholder="Qualification"><input name="location" value="{{ request('location') }}" placeholder="Location"></div><div class="filterActions"><button class="btn green" type="submit">Search Opportunities</button>@if(request()->hasAny(['q','type','qualification','location']))<a class="btn alt" href="{{ route('jobs.index') }}">Clear Filters</a>@endif</div></form><div class="jobs">@forelse($jobs as $job)<article class="job"><div><span class="tag">{{ ucfirst($job->job_type) }}</span>@if($job->is_featured)<span class="tag featured">Featured</span>@endif @if($job->category)<span class="tag">{{ $job->category }}</span>@endif</div><h2>{{ $job->title }}</h2><div class="muted">{{ $job->organization }}</div>@if($job->qualification)<p><strong>Qualification:</strong> {{ $job->qualification }}</p>@endif @if($job->location)<p><strong>Location:</strong> {{ $job->location }}</p>@endif @if($job->last_date)<p class="deadline">Apply by {{ $job->last_date->format('d M Y') }}</p>@endif @if($job->summary)<p>{{ $job->summary }}</p>@endif<div class="actions"><a class="btn green" href="{{ route('jobs.official',$job) }}" target="_blank" rel="noopener noreferrer nofollow">Official Apply / Details ↗</a>@auth @if(auth()->user()->role==='student')<form method="POST" action="{{ route('student.saved-jobs.store',$job) }}">@csrf<button class="btn alt" type="submit">Save Job</button></form>@endif @endauth</div></article>@empty<div class="card empty"><h2>No matching active opportunities</h2><p class="muted">Try clearing one or more filters to broaden the results.</p><a class="btn alt" href="{{ route('jobs.index') }}">Show All Active Jobs</a></div>@endforelse</div><div style="margin-top:20px">{{ $jobs->links() }}</div><div class="footnote">C-Net Library summarizes opportunities for convenience. Always verify eligibility, dates, fees and instructions on the linked official source before applying.</div></div></body></html>